const REDASH='https://redash.intermesh.net'; const RKEY='u39CfxKyFrTeXmGYyaXwy0uuNrJ0SsRnrJeuIn4y'; const QID=12158; const PARAM='mcatid'; const IDCOL='glcat_mcat_id'; const NAMECOL='glcat_mcat_name'; const MAXAGE=2592000;
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const http=this.helpers.httpRequest.bind(this.helpers);
const parseLoose=s=>{ if(s&&typeof s==='object') return s; try{ return JSON.parse(String(s).replace(/[\u0000-\u001F]+/g,' ')); }catch(e){ return null; } };
let ids=[]; try{ ids=($('csl-to-llm').first().json.summary._enrich['mcat_ids'])||[]; }catch(e){}
