else { const ck=ids.slice().sort().join(','); if(ck && cache['__'+ck]!==undefined){ for(const n of cache['__'+ck]) namesAll.push(n); } else need=ids.slice(); }
let rows=[];
if(need.length){
  try{
    let tj=null;
    for(let a=0;a<4 && !tj;a++){ try{ tj=await http({method:'POST',url:REDASH+'/api/queries/'+QID+'/results',headers:{Authorization:'Key '+RKEY,'Content-Type':'application/json'},body:{parameters:{[PARAM]:'ANY(ARRAY['+need.join(',')+'])'},max_age:MAXAGE},json:true,timeout:40000}); }catch(e){ tj=null; await sleep(1000); } }
    if(tj){ let r=tj.query_result&&tj.query_result.data&&tj.query_result.data.rows;
      if(!r){ const jid=tj.job&&tj.job.id; let qrid=(tj.job&&tj.job.query_result_id)||null; let st=tj.job&&tj.job.status; const end=Date.now()+120000;
        while(Date.now()<end && !qrid){ await sleep(2500); let pj=null; try{ pj=await http({method:'GET',url:REDASH+'/api/jobs/'+jid+'?api_key='+RKEY,json:true,timeout:20000}); }catch(e){} st=pj&&pj.job&&pj.job.status; if(st===3) qrid=pj.job.query_result_id; else if(st===4) break; }
        if(qrid){ const raw=await http({method:'GET',url:REDASH+'/api/query_results/'+qrid+'.json?api_key='+RKEY,json:false,timeout:25000}); const rj=parseLoose(raw); r=(rj&&rj.query_result&&rj.query_result.data&&rj.query_result.data.rows)||[]; } }
