// ---- parseWAconv: VERBATIM from v9.5 wa-conv-parser ----
function parseWAconv(input){
  const recs=(input&&input.data&&input.data.records)||[];
  const buyer=[]; const offered=new Set();
  for(const r of recs){ let d={}; try{ d=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){}
    if(r.eto_lead_attribute==='USER'){ const t=d.text||d.title; if(t) buyer.push(fixNull({date:r.insert_date,text:t})); }
    else { const cap=d.caption||d.text||''; const m=cap.match(/Need \*([^*]+)\* in \*([^*]+)\*/)||cap.match(/sellers of \*([^*]+)\* in \*([^*]+)\*/); if(m) offered.add(`${m[1]} (${m[2]})`); }
  }
  const OBJ_RE=/high price|not satisfied|need more sellers|no response|located too far|product unavailable|too far|expensive|costly/i;
  const objections=dedupeCI(buyer.map(b=>b.text).filter(t=>t&&OBJ_RE.test(t)));
  const dissatisfaction_count=buyer.filter(b=>/not satisfied|👎/i.test(b.text||'')).length;
  const locPref=[]; for(const b of buyer){ const t=String(b.text||''); const m=t.match(/^([A-Z][a-z]{2,})\s+(?:btao|chahiye|wale|wala|me|mein)\b/i); if(m) locPref.push(m[1]); else if(/near me|located near|aas ?paas|\bpaas\b/i.test(t)) locPref.push('Near me'); }
  const reqs=[]; for(const r of recs){ if(r.eto_lead_attribute==='USER') continue; let dd={}; try{ dd=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){} const tx=dd.text||(dd.interactive&&dd.interactive.body&&dd.interactive.body.text)||''; const mm=String(tx).match(/requirement for (.+?) has been (?:received|sent)/i); if(mm) reqs.push(mm[1].trim()); }
  const sellers=[]; const seenS=new Set();
  for(const r of recs){ if(r.eto_lead_attribute==='USER') continue; let dd={}; try{ dd=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){}
    const body=String((dd.interactive&&dd.interactive.body&&dd.interactive.body.text)||dd.caption||dd.text||'');
    const rt=body.match(/⭐\s*([0-9.]+)\s*\(([0-9]+)\)/); const pr=body.match(/(?:₹|Rs\.?|INR)\s*([0-9,]+)/i);
    let m=body.match(/^\*?([A-Z][^\n*(]{2,50}?)\*?\s*\(([^)\n]+)\)/);
    let name=null, city=null;
    if(m){ name=m[1].trim(); city=m[2].trim(); } else { const m2=body.match(/^\*([^*\n]{2,50})\*/); if(m2 && pr) name=m2[1].trim(); }
    if(name){ const k=name.toLowerCase(); if(!seenS.has(k)){ seenS.add(k); sellers.push(fixNull({ name, city, rating: rt?parseFloat(rt[1]):undefined, reviews: rt?parseInt(rt[2],10):undefined, price: pr?('₹'+pr[1]):undefined })); } } }
  const price_points=dedupeCI(sellers.map(s=>s.price).filter(Boolean));
  return fixNull({ buyer_messages:buyer, products_offered:[...offered], objections, dissatisfaction_count, location_preference:dedupeCI(locPref), requirements_discussed:dedupeCI(reqs), sellers_shown:sellers, price_points, message_count:recs.length });
}

// ---- parseWAinbound: VERBATIM from v9.5 wa-inbound-parser ----
function parseWAinbound(input){
  const msgs=(input&&input.data&&input.data.recent_messages)||[];
  const enq=[], prodSet=[], sellerSet=[], citySet=[];
  for(const m of msgs){ const c=(m.content||'').replace(/\r/g,''); let product=null,seller=null,city=null,mm;
    if((mm=c.match(/requirement for\s+(.+?)\s+has been sent to\s+([^.\n]+?)\.?\s*$/im))){ product=mm[1].trim(); seller=mm[2].trim(); }
    else if((mm=c.match(/has been sent to\s+([^.\n]+?)\.?\s*$/im))){ seller=mm[1].trim(); }
    if(!product && (mm=c.match(/requirement for\s+(.+?)\s+has been (?:sent|received)/im))) product=mm[1].trim();
    if(!seller && (mm=c.match(/(?:connect with|spoke with|connected with)\s*\*?([^*\n?]+?)\*?\s*[?📞\n]/i))) seller=mm[1].trim();
    if(!seller && /📞|indiamart\.com|TrustSEAL|GST Verified/i.test(c) && (mm=c.match(/^\s*([A-Z][^\n(]{2,}?)\s*\(([^)\n]+)\)\s*$/m))){ seller=mm[1].trim(); city=mm[2].trim(); }
    if(product) prodSet.push(product);
    if(seller && seller.length<60) sellerSet.push(seller);
    if(city) citySet.push(city);
    if(product||seller) enq.push(fixNull({ date:m.timestamp, product, seller, seller_city:city }));
  }
  const typedEnq=[]; const locPref=[]; let posFb=0, negFb=0;
  for(const m of msgs){ if(m.sender!=='user') continue; const c=String(m.content||'').replace(/\r/g,'');
    const ne=c.match(/Need best price for\s+([^\n,]+?)(?:,\s*([0-9]+\s*Gsm))?(?:\n|$)/i); if(ne) typedEnq.push(fixNull({ product:ne[1].trim(), gsm:ne[2]?ne[2].trim():undefined }));
    if(/👍|yes,?\s*perfect/i.test(c)) posFb++;
    if(/👎|not satisfied/i.test(c)) negFb++;
    if(/located near me|near me|aas ?paas|\bpaas\b/i.test(c)) locPref.push('Near me'); }
  return fixNull({ enquiries:enq, products:dedupeCI(prodSet), sellers_shared:dedupeCI(sellerSet), seller_cities:dedupeCI(citySet), buyer_typed_enquiries:typedEnq, location_preference:dedupeCI(locPref), positive_feedback:posFb, negative_feedback:negFb, message_count:input&&input.data&&input.data.message_count });
}

// ====================== MERGE: ONE timeline ======================
const root = x => Array.isArray(x) ? (x[0]||{}) : (x||{});
const tsOf = s => { if(!s) return null; const str=String(s).trim(); const iso = /[zZ]|[+-]\d{2}:?\d{2}$/.test(str) ? str : str.replace(' ','T')+'Z'; const t=Date.parse(iso); return Number.isFinite(t)?t:null; };
const clip = (s,n=400) => { const t=String(s==null?'':s).replace(/\r/g,'').trim(); return t.length>n?t.slice(0,n):t; };

// NOISE we REJECT entirely (OTP/verification, footer/unsubscribe, code/status/handles)
const OTP_RE   = /\b(?:OTP|one[- ]time password|verification code|verify your|\d{4,8}\s+is your)\b/i;
const FOOTER_RE= /type ['"]?stop['"]? to unsubscribe|unsubscribe|you will not receive any further message/i;
// media/carousel/handle junk that sometimes lands in a text field
const HANDLE_RE= /header_handle|aW1hZ2|imimg\.com\/data5|AiSensy-file/i;

// our-side caption product/location extractor (context, kept lightly)
function ourCaptionMeta(text){
  const m = text.match(/Need \*([^*]+)\* in \*([^*]+)\*/) || text.match(/sellers of \*([^*]+)\* in \*([^*]+)\*/) || text.match(/\*([^*]+)\* ka \*([^*]+)\* mein best price/);
  return m ? { product: m[1].trim(), location: m[2].trim() } : null;
}

// ---- BORROWED (intern whatsapp_outbound_structuer): campaign-funnel KPIs ----
// API record with a YES-prompt = a campaign we sent; USER record = buyer responded.
// VERBATIM intern logic, hardened with try/catch + safe optional access.
function computeCampaignFunnel(convIn){
  const recs = (convIn && convIn.data && Array.isArray(convIn.data.records)) ? convIn.data.records : [];
  let campaigns_received=0, campaigns_responded=0, yes_responses=0, no_responses=0;
  for (const r of recs){
    let detail={}; try { detail = JSON.parse((r&&r.eto_lead_attribute_detail) || '{}'); } catch(e){ continue; }
    if (r && r.eto_lead_attribute === 'API'){
      let blob='';
      if (detail.caption) blob += ' ' + detail.caption;
      if (detail.text) blob += ' ' + detail.text;
      if (detail.interactive && detail.interactive.body && detail.interactive.body.text) blob += ' ' + detail.interactive.body.text;
      if (blob.includes('YES') || blob.includes('Yes') || blob.includes('Reply with YES')) campaigns_received++;
    }
    if (r && r.eto_lead_attribute === 'USER'){
      campaigns_responded++;
      const response = String(detail.text || '').trim().toLowerCase();
      if (response === 'yes') yes_responses++;
      if (response === 'no') no_responses++;
    }
  }
  let response_rate = 0;
  if (campaigns_received > 0){
    response_rate = Math.min(100, Math.round((yes_responses / Math.max(1, campaigns_received)) * 100)); // v38: YES-replies only
  }
  return { campaigns_received, campaigns_responded, response_rate, yes_responses, no_responses };
}

// ---- BORROWED (intern whatsapp_inbound_structurer): discrete inbound flags ----
// VERBATIM intern detection strings, hardened with safe content access.
function computeInboundFlags(inbIn){
  const msgs = (inbIn && inbIn.data && Array.isArray(inbIn.data.recent_messages)) ? inbIn.data.recent_messages : [];
  const has = (needle) => msgs.some(m => typeof (m&&m.content) === 'string' && m.content.includes(needle));
  const images_requested = has('Share photos');
  const supplier_feedback_given = has('Not Satisfied') || has('Seller helpful');
  const intentSet = new Set();
  for (const m of msgs){
    const text = String((m && m.content) || '').toLowerCase();
    if (text.includes('reselling'))    intentSet.add('reselling');
    if (text.includes('distribution')) intentSet.add('distribution');
    if (text.includes('wholesale'))    intentSet.add('wholesale');
  }
  return { images_requested, explicit_business_intent: [...intentSet], supplier_feedback_given };
}

function buildTimeline(convIn, inbIn){
  const turns = [];
  const products_offered = new Set();   // what WE pitched (context)
  const products_enquired = new Set();   // what BUYER asked for (signal)
  const button_taps = [];                // buyer button/quick-reply taps (signal)
  let rejected = 0;

  // ---------- OUTBOUND (whatsapp-conversations: records[]) ----------
  const recs = (convIn && convIn.data && convIn.data.records) || [];
  for (const r of recs){
    let d={}; try{ d=JSON.parse(r.eto_lead_attribute_detail||'{}'); }catch(e){}
    const ts = tsOf(r.insert_date);
    const isBuyer = r.eto_lead_attribute === 'USER';

    if (isBuyer){
      // BUYER side of the outbound channel = quick-reply taps, ISQ-option taps, ISQ-flow submissions, free text
      // 1) WhatsApp Flow / ISQ-spec form submission (response_json) — high-value spec answer
      if (d.response_json){
        let rj={}; try{ rj=JSON.parse(d.response_json); }catch(e){}
        const parts=[];
        if(rj.PRODUCT_NAME) parts.push(rj.PRODUCT_NAME);
        if(rj.INPUT_RECEIVED) parts.push(rj.INPUT_RECEIVED + (rj.QUANTITY_UNIT?(' '+rj.QUANTITY_UNIT):''));
        else if(rj.QUANTITY_UNIT) parts.push(rj.QUANTITY_UNIT);
        if(rj.DISPOSITION) parts.push(rj.DISPOSITION);
        const text = clip(parts.filter(Boolean).join(' · ') || d.body || 'spec submitted');
        if(rj.PRODUCT_NAME) products_enquired.add(rj.PRODUCT_NAME.trim());
        turns.push({ ts, sender:'buyer', kind:'isq_answer', text, channel:'outbound' });
        continue;
      }
      // 2) explicit text or button title
      const raw = d.text || d.title || '';
      const text = clip(raw);
      if (!text){ rejected++; continue; }
      if (OTP_RE.test(text) || FOOTER_RE.test(text) || HANDLE_RE.test(text)){ rejected++; continue; }
      // a callbackPayload OR an `id`+`title` (ISQ option) means it's a tap, not free text
      const isTap = !!d.callbackPayload || (d.id!=null && d.title!=null) || /^(yes|no|stop|y|n)$/i.test(text);
      // ISQ-option taps carry a meaningful selected value as `title`
      const kind = d.callbackPayload && /^(yes|no|stop|y|n)$/i.test(text) ? 'button_tap'
                 : (d.title!=null && d.callbackPayload==null) ? 'isq_answer'
                 : isTap ? 'button_tap' : 'free_text';
      if (kind==='button_tap' || kind==='isq_answer') button_taps.push(text);
      turns.push({ ts, sender:'buyer', kind, text, channel:'outbound' });
    } else {
      // API = OURS (context). Keep caption/body text; reject pure media/carousel/footer noise.
      const body = String((d.interactive&&d.interactive.body&&d.interactive.body.text) || d.caption || d.text || '');
      const text = clip(body);
      if (text){
        const meta = ourCaptionMeta(text);
        if (meta && meta.product) products_offered.add(`${meta.product} (${meta.location})`);
      }
      // skip footer-only / handle-only / empty -> still a turn but flagged; reject if nothing usable
      if (!text || HANDLE_RE.test(text)){ rejected++; continue; }
      const isFooter = FOOTER_RE.test(text);
      turns.push({ ts, sender:'ours', kind: isFooter?'footer':'caption', text, channel:'outbound' });
    }
  }

  // ---------- INBOUND (whatsapp-inbound: recent_messages[]) ----------
  const msgs = (inbIn && inbIn.data && inbIn.data.recent_messages) || [];
  for (const m of msgs){
    const ts = tsOf(m.timestamp);
    const content = clip(m.content);
    if (!content){ rejected++; continue; }
    if (OTP_RE.test(content) || HANDLE_RE.test(content)){ rejected++; continue; }
    const isBuyer = m.sender === 'user';   // user=buyer, bot=ours
    if (isBuyer){
      const kind = m.message_type === 'clicked' ? 'button_tap' : 'free_text';
      if (kind==='button_tap') button_taps.push(content);
      // typed buyer messages that look like a product enquiry feed products_enquired
      const ne = content.match(/Need best price for\s+([^\n,]+)/i);
      if (ne) products_enquired.add(ne[1].trim());
      turns.push({ ts, sender:'buyer', kind, text:content, channel:'inbound' });
    } else {
      // bot = OURS (context). Reject footer/unsubscribe only.
      if (FOOTER_RE.test(content)){ rejected++; continue; }
      turns.push({ ts, sender:'ours', kind:'caption', text:content, channel:'inbound' });
    }
  }

  // ---------- sort by ts (nulls last, stable) ----------
  turns.forEach((t,i)=>{ t._i=i; });
  turns.sort((a,b)=>{
    const at=a.ts, bt=b.ts;
    if(at==null && bt==null) return a._i-b._i;
    if(at==null) return 1;
    if(bt==null) return -1;
    if(at!==bt) return at-bt;
    return a._i-b._i;
  });
  turns.forEach(t=>{ delete t._i; });

  const buyer_turns = turns.filter(t=>t.sender==='buyer').length;
  const our_turns   = turns.filter(t=>t.sender==='ours').length;
  // responsive = buyer ever replied after we reached out
  const NAV_TAP = /register as seller|call indiamart|raise a complaint|need help|^\s*buy\s*$|located near me|^\s*view\b|^\s*more\s*$/i;
  const navTaps = dedupeCI(button_taps).filter(function(t){ return NAV_TAP.test(String(t)); }).length;
  const meaningful_buyer_turns = Math.max(0, buyer_turns - navTaps);
  let responsive = false;
  if (buyer_turns>0 && our_turns>0){
    const firstOurs = turns.findIndex(t=>t.sender==='ours');
    responsive = turns.slice(firstOurs+1).some(t=>t.sender==='buyer' && !NAV_TAP.test(String(t.text||t.content||'')));
    if(!responsive) responsive = meaningful_buyer_turns>0;
  } else if (meaningful_buyer_turns>0){
    responsive = true;
  }

  return {
    timeline: turns,
    summary: {
      products_offered: [...products_offered],
      products_enquired: [...products_enquired],
      button_taps: dedupeCI(button_taps),
      counts: { buyer_turns, meaningful_buyer_turns, our_turns, total: turns.length, responsive }
    }
  };
}

